package oci

import "errors"

const (
	// MediaTypeFliptFeatures is the OCI media type for a flipt features artifact
	MediaTypeFliptFeatures = "application/vnd.io.flipt.features.v1"
	// MediaTypeFliptNamespace is the OCI media type for a flipt features namespace artifact
	MediaTypeFliptNamespace = "application/vnd.io.flipt.features.namespace.v1"

	// AnnotationFliptNamespace is an OCI annotation key which identifies the namespace key
	// of the annotated flipt namespace artifact
	AnnotationFliptNamespace = "io.flipt.features.namespace"
)

var (
	// ErrMissingMediaType is returned when a descriptor is presented
	// without a media type
	ErrMissingMediaType = errors.New("missing media type")
	// ErrUnexpectedMediaType is returned when an unexpected media type
	// is found on a target manifest or descriptor
	ErrUnexpectedMediaType = errors.New("unexpected media type")
)
package oci

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"path"
	"strings"
	"time"

	"github.com/opencontainers/go-digest"
	v1 "github.com/opencontainers/image-spec/specs-go/v1"
	"go.flipt.io/flipt/internal/config"
	"go.flipt.io/flipt/internal/containers"
	"oras.land/oras-go/v2"
	"oras.land/oras-go/v2/content"
	"oras.land/oras-go/v2/content/memory"
	"oras.land/oras-go/v2/content/oci"
	"oras.land/oras-go/v2/registry"
	"oras.land/oras-go/v2/registry/remote"
)

// Store is a type which can retrieve Flipt feature files from a target repository and reference
// Repositories can be local (OCI layout directories on the filesystem) or a remote registry
type Store struct {
	reference registry.Reference
	store     oras.ReadOnlyTarget
	local     oras.Target
}

// NewStore constructs and configures an instance of *Store for the provided config
func NewStore(conf *config.OCI) (*Store, error) {
	scheme, repository, match := strings.Cut(conf.Repository, "://")

	// support empty scheme as remote and https
	if !match {
		repository = scheme
		scheme = "https"
	}

	ref, err := registry.ParseReference(repository)
	if err != nil {
		return nil, err
	}

	store := &Store{
		reference: ref,
		local:     memory.New(),
	}
	switch scheme {
	case "http", "https":
		remote, err := remote.NewRepository(fmt.Sprintf("%s/%s", ref.Registry, ref.Repository))
		if err != nil {
			return nil, err
		}

		remote.PlainHTTP = scheme == "http"

		store.store = remote
	case "flipt":
		if ref.Registry != "local" {
			return nil, fmt.Errorf("unexpected local reference: %q", conf.Repository)
		}

		store.store, err = oci.New(path.Join(conf.BundleDirectory, ref.Repository))
		if err != nil {
			return nil, err
		}
	default:
		return nil, fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
	}

	return store, nil
}

// FetchOptions configures a call to Fetch
type FetchOptions struct {
	IfNoMatch digest.Digest
}

// FetchResponse contains any fetched files for the given tracked reference
// If Matched == true, then the supplied IfNoMatch digest matched and Files should be nil
type FetchResponse struct {
	Digest  digest.Digest
	Files   []fs.File
	Matched bool
}

// IfNoMatch configures the call to Fetch to return early if the supplied
// digest matches the target manifest pointed at by the underlying reference
// This is a cache optimization to skip re-fetching resources if the contents
// has already been seen by the caller
func IfNoMatch(digest digest.Digest) containers.Option[FetchOptions] {
	return func(fo *FetchOptions) {
		fo.IfNoMatch = digest
	}
}

// Fetch retrieves the associated files for the tracked repository and reference
// It can optionally be configured to skip fetching given the caller has a digest
// that matches the current reference target
func (s *Store) Fetch(ctx context.Context, opts ...containers.Option[FetchOptions]) (*FetchResponse, error) {
	var options FetchOptions
	containers.ApplyAll(&options, opts...)

	desc, err := oras.Copy(ctx,
		s.store,
		s.reference.Reference,
		s.local,
		s.reference.Reference,
		oras.DefaultCopyOptions)
	if err != nil {
		return nil, err
	}

	bytes, err := content.FetchAll(ctx, s.local, desc)
	if err != nil {
		return nil, err
	}

	var manifest v1.Manifest
	if err = json.Unmarshal(bytes, &manifest); err != nil {
		return nil, err
	}

	var d digest.Digest
	{
		// shadow manifest so that we can safely
		// strip annotations before calculating
		// the digest
		manifest := manifest
		manifest.Annotations = map[string]string{}
		bytes, err := json.Marshal(&manifest)
		if err != nil {
			return nil, err
		}

		d = digest.FromBytes(bytes)
		if d == options.IfNoMatch {
			return &FetchResponse{Matched: true, Digest: d}, nil
		}
	}

	files, err := s.fetchFiles(ctx, manifest)
	if err != nil {
		return nil, err
	}

	return &FetchResponse{Files: files, Digest: d}, nil
}

// fetchFiles retrieves the associated flipt feature content files from the content fetcher.
// It traverses the provided manifests and returns a slice of file instances with appropriate
// content type extensions.
func (s *Store) fetchFiles(ctx context.Context, manifest v1.Manifest) ([]fs.File, error) {
	var files []fs.File

	created, err := time.Parse(time.RFC3339, manifest.Annotations[v1.AnnotationCreated])
	if err != nil {
		return nil, err
	}

	for _, layer := range manifest.Layers {
		mediaType, encoding, err := getMediaTypeAndEncoding(layer)
		if err != nil {
			return nil, fmt.Errorf("layer %q: %w", layer.Digest, err)
		}

		if mediaType != MediaTypeFliptNamespace {
			return nil, fmt.Errorf("layer %q: type %q: %w", layer.Digest, mediaType, ErrUnexpectedMediaType)
		}

		switch encoding {
		case "", "json", "yaml", "yml":
		default:
			return nil, fmt.Errorf("layer %q: unexpected layer encoding: %q", layer.Digest, encoding)
		}

		rc, err := s.store.Fetch(ctx, layer)
		if err != nil {
			return nil, err
		}

		files = append(files, &File{
			ReadCloser: rc,
			info: FileInfo{
				desc:     layer,
				encoding: encoding,
				mod:      created,
			},
		})
	}

	return files, nil
}

func getMediaTypeAndEncoding(layer v1.Descriptor) (mediaType, encoding string, _ error) {
	var ok bool
	if mediaType = layer.MediaType; mediaType == "" {
		return "", "", ErrMissingMediaType
	}

	if mediaType, encoding, ok = strings.Cut(mediaType, "+"); !ok {
		encoding = "json"
	}

	return
}

// File is a wrapper around a flipt feature state files contents.
type File struct {
	io.ReadCloser
	info FileInfo
}

// Seek attempts to seek the embedded read-closer.
// If the embedded read closer implements seek, then it delegates
// to that instances implementation. Alternatively, it returns
// an error signifying that the File cannot be seeked.
func (f *File) Seek(offset int64, whence int) (int64, error) {
	if seek, ok := f.ReadCloser.(io.Seeker); ok {
		return seek.Seek(offset, whence)
	}

	return 0, errors.New("seeker cannot seek")
}

func (f *File) Stat() (fs.FileInfo, error) {
	return &f.info, nil
}

// FileInfo describes a flipt features state file instance.
type FileInfo struct {
	desc     v1.Descriptor
	encoding string
	mod      time.Time
}

func (f FileInfo) Name() string {
	return f.desc.Digest.Hex() + "." + f.encoding
}

func (f FileInfo) Size() int64 {
	return f.desc.Size
}

func (f FileInfo) Mode() fs.FileMode {
	return fs.ModePerm
}

func (f FileInfo) ModTime() time.Time {
	return f.mod
}

func (f FileInfo) IsDir() bool {
	return false
}

func (f FileInfo) Sys() any {
	return nil
}

package fs

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"sort"
	"strconv"

	"github.com/gobwas/glob"
	"github.com/gofrs/uuid"
	errs "go.flipt.io/flipt/errors"
	"go.flipt.io/flipt/internal/cue"
	"go.flipt.io/flipt/internal/ext"
	"go.flipt.io/flipt/internal/storage"
	"go.flipt.io/flipt/rpc/flipt"
	"go.uber.org/zap"
	"google.golang.org/protobuf/types/known/timestamppb"
	"gopkg.in/yaml.v3"
)

const (
	indexFile = ".flipt.yml"
	defaultNs = "default"
)

var (
	_                 storage.Store = (*StoreSnapshot)(nil)
	ErrNotImplemented               = errors.New("not implemented")
)

// FliptIndex represents the structure of a well-known file ".flipt.yml"
// at the root of an FS.
type FliptIndex struct {
	Version string   `yaml:"version,omitempty"`
	Include []string `yaml:"include,omitempty"`
	Exclude []string `yaml:"exclude,omitempty"`
}

// StoreSnapshot contains the structures necessary for serving
// flag state to a client.
type StoreSnapshot struct {
	ns        map[string]*namespace
	evalDists map[string][]*storage.EvaluationDistribution
	now       *timestamppb.Timestamp
}

type namespace struct {
	resource     *flipt.Namespace
	flags        map[string]*flipt.Flag
	segments     map[string]*flipt.Segment
	rules        map[string]*flipt.Rule
	rollouts     map[string]*flipt.Rollout
	evalRules    map[string][]*storage.EvaluationRule
	evalRollouts map[string][]*storage.EvaluationRollout
}

func newNamespace(key, name string, created *timestamppb.Timestamp) *namespace {
	return &namespace{
		resource: &flipt.Namespace{
			Key:       key,
			Name:      name,
			CreatedAt: created,
			UpdatedAt: created,
		},
		flags:        map[string]*flipt.Flag{},
		segments:     map[string]*flipt.Segment{},
		rules:        map[string]*flipt.Rule{},
		rollouts:     map[string]*flipt.Rollout{},
		evalRules:    map[string][]*storage.EvaluationRule{},
		evalRollouts: map[string][]*storage.EvaluationRollout{},
	}
}

// SnapshotFromFS is a convenience function for building a snapshot
// directly from an implementation of fs.FS using the list state files
// function to source the relevant Flipt configuration files.
func SnapshotFromFS(logger *zap.Logger, fs fs.FS) (*StoreSnapshot, error) {
	files, err := listStateFiles(logger, fs)
	if err != nil {
		return nil, err
	}

	logger.Debug("opening state files", zap.Strings("paths", files))

	return SnapshotFromPaths(fs, files...)
}

// SnapshotFromPaths constructs a StoreSnapshot from the provided
// slice of paths resolved against the provided fs.FS.
func SnapshotFromPaths(ffs fs.FS, paths ...string) (*StoreSnapshot, error) {
	var files []fs.File
	for _, file := range paths {
		fi, err := ffs.Open(file)
		if err != nil {
			return nil, err
		}

		files = append(files, fi)
	}

	return SnapshotFromFiles(files...)
}

// SnapshotFromFiles constructs a StoreSnapshot from the provided slice
// of fs.File implementations.
func SnapshotFromFiles(files ...fs.File) (*StoreSnapshot, error) {
	validator, err := cue.NewFeaturesValidator()
	if err != nil {
		return nil, err
	}

	now := timestamppb.Now()
	s := StoreSnapshot{
		ns: map[string]*namespace{
			defaultNs: newNamespace("default", "Default", now),
		},
		evalDists: map[string][]*storage.EvaluationDistribution{},
		now:       now,
	}

	for _, fi := range files {
		if err := func() error {
			defer fi.Close()

			stat, err := fi.Stat()
			if err != nil {
				return err
			}

			buf := &bytes.Buffer{}
			reader := io.TeeReader(fi, buf)

			if err := validator.Validate(stat.Name(), reader); err != nil {
				return err
			}

			decoder := yaml.NewDecoder(buf)
			// Support YAML stream by looping until we reach an EOF.
			for {
				doc := new(ext.Document)

				if err := decoder.Decode(doc); err != nil {
					if errors.Is(err, io.EOF) {
						break
					}
					return err
				}

				// set namespace to default if empty in document
				if doc.Namespace == "" {
					doc.Namespace = "default"
				}

				if err := s.addDoc(doc); err != nil {
					return err
				}
			}

			return nil
		}(); err != nil {
			return nil, err
		}
	}

	return &s, nil
}

func listStateFiles(logger *zap.Logger, source fs.FS) ([]string, error) {
	// This is the default variable + value for the FliptIndex. It will preserve its value if
	// a .flipt.yml can not be read for whatever reason.
	idx := FliptIndex{
		Version: "1.0",
		Include: []string{
			"**features.yml", "**features.yaml", "**.features.yml", "**.features.yaml",
		},
	}

	// Read index file
	inFile, err := source.Open(indexFile)
	if err == nil {
		if derr := yaml.NewDecoder(inFile).Decode(&idx); derr != nil {
			return nil, fmt.Errorf("yaml: %w", derr)
		}
	}

	if err != nil {
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err
		} else {
			logger.Debug("index file does not exist, defaulting...", zap.String("file", indexFile), zap.Error(err))
		}
	}

	var includes []glob.Glob
	for _, g := range idx.Include {
		glob, err := glob.Compile(g)
		if err != nil {
			return nil, fmt.Errorf("compiling include glob: %w", err)
		}

		includes = append(includes, glob)
	}

	filenames := make([]string, 0)
	if err := fs.WalkDir(source, ".", func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		if d.IsDir() {
			return nil
		}

		for _, glob := range includes {
			if glob.Match(path) {
				filenames = append(filenames, path)
				return nil
			}
		}

		return nil
	}); err != nil {
		return nil, err
	}

	if len(idx.Exclude) > 0 {
		var excludes []glob.Glob
		for _, g := range idx.Exclude {
			glob, err := glob.Compile(g)
			if err != nil {
				return nil, fmt.Errorf("compiling include glob: %w", err)
			}

			excludes = append(excludes, glob)
		}

	OUTER:
		for i := range filenames {
			for _, glob := range excludes {
				if glob.Match(filenames[i]) {
					filenames = append(filenames[:i], filenames[i+1:]...)
					continue OUTER
				}
			}
		}
	}

	return filenames, nil
}

func (ss *StoreSnapshot) addDoc(doc *ext.Document) error {
	ns := ss.ns[doc.Namespace]
	if ns == nil {
		ns = newNamespace(doc.Namespace, doc.Namespace, ss.now)
	}

	evalDists := map[string][]*storage.EvaluationDistribution{}
	if len(ss.evalDists) > 0 {
		evalDists = ss.evalDists
	}

	for _, s := range doc.Segments {
		matchType := flipt.MatchType_value[s.MatchType]
		segment := &flipt.Segment{
			NamespaceKey: doc.Namespace,
			Name:         s.Name,
			Key:          s.Key,
			Description:  s.Description,
			MatchType:    flipt.MatchType(matchType),
			CreatedAt:    ss.now,
			UpdatedAt:    ss.now,
		}

		for _, constraint := range s.Constraints {
			constraintType := flipt.ComparisonType_value[constraint.Type]
			segment.Constraints = append(segment.Constraints, &flipt.Constraint{
				NamespaceKey: doc.Namespace,
				SegmentKey:   segment.Key,
				Id:           uuid.Must(uuid.NewV4()).String(),
				Operator:     constraint.Operator,
				Property:     constraint.Property,
				Type:         flipt.ComparisonType(constraintType),
				Value:        constraint.Value,
				Description:  constraint.Description,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			})
		}

		ns.segments[segment.Key] = segment
	}

	for _, f := range doc.Flags {
		flagType := flipt.FlagType_value[f.Type]
		flag := &flipt.Flag{
			NamespaceKey: doc.Namespace,
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			Type:         flipt.FlagType(flagType),
			CreatedAt:    ss.now,
			UpdatedAt:    ss.now,
		}

		for _, v := range f.Variants {
			attachment, err := json.Marshal(v.Attachment)
			if err != nil {
				return err
			}

			flag.Variants = append(flag.Variants, &flipt.Variant{
				Id:           uuid.Must(uuid.NewV4()).String(),
				NamespaceKey: doc.Namespace,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(attachment),
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			})
		}

		ns.flags[f.Key] = flag

		evalRules := []*storage.EvaluationRule{}
		for i, r := range f.Rules {
			rank := int32(i + 1)
			rule := &flipt.Rule{
				NamespaceKey: doc.Namespace,
				Id:           uuid.Must(uuid.NewV4()).String(),
				FlagKey:      f.Key,
				Rank:         rank,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			evalRule := &storage.EvaluationRule{
				NamespaceKey: doc.Namespace,
				FlagKey:      f.Key,
				ID:           rule.Id,
				Rank:         rank,
			}

			switch s := r.Segment.IsSegment.(type) {
			case ext.SegmentKey:
				rule.SegmentKey = string(s)
			case *ext.Segments:
				rule.SegmentKeys = s.Keys
				segmentOperator := flipt.SegmentOperator_value[s.SegmentOperator]

				rule.SegmentOperator = flipt.SegmentOperator(segmentOperator)
			}

			var (
				segmentKeys = []string{}
				segments    = make(map[string]*storage.EvaluationSegment)
			)

			if rule.SegmentKey != "" {
				segmentKeys = append(segmentKeys, rule.SegmentKey)
			} else if len(rule.SegmentKeys) > 0 {
				segmentKeys = append(segmentKeys, rule.SegmentKeys...)
			}

			for _, segmentKey := range segmentKeys {
				segment := ns.segments[segmentKey]
				if segment == nil {
					return errs.ErrInvalidf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, rank, segmentKey)
				}

				evc := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
				for _, constraint := range segment.Constraints {
					evc = append(evc, storage.EvaluationConstraint{
						Operator: constraint.Operator,
						Property: constraint.Property,
						Type:     constraint.Type,
						Value:    constraint.Value,
					})
				}

				segments[segmentKey] = &storage.EvaluationSegment{
					SegmentKey:  segmentKey,
					MatchType:   segment.MatchType,
					Constraints: evc,
				}
			}

			if rule.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
				evalRule.SegmentOperator = flipt.SegmentOperator_AND_SEGMENT_OPERATOR
			}

			evalRule.Segments = segments

			evalRules = append(evalRules, evalRule)

			for _, d := range r.Distributions {
				variant, found := findByKey(d.VariantKey, flag.Variants...)
				if !found {
					return errs.ErrInvalidf("flag %s/%s rule %d references unknown variant %q", doc.Namespace, flag.Key, rank, d.VariantKey)
				}

				id := uuid.Must(uuid.NewV4()).String()
				rule.Distributions = append(rule.Distributions, &flipt.Distribution{
					Id:        id,
					Rollout:   d.Rollout,
					RuleId:    rule.Id,
					VariantId: variant.Id,
					CreatedAt: ss.now,
					UpdatedAt: ss.now,
				})

				evalDists[evalRule.ID] = append(evalDists[evalRule.ID], &storage.EvaluationDistribution{
					ID:                id,
					Rollout:           d.Rollout,
					VariantID:         variant.Id,
					VariantKey:        variant.Key,
					VariantAttachment: variant.Attachment,
				})
			}

			ns.rules[rule.Id] = rule
		}

		ns.evalRules[f.Key] = evalRules

		evalRollouts := make([]*storage.EvaluationRollout, 0, len(f.Rollouts))
		for i, rollout := range f.Rollouts {
			rank := int32(i + 1)
			s := &storage.EvaluationRollout{
				NamespaceKey: doc.Namespace,
				Rank:         rank,
			}

			flagRollout := &flipt.Rollout{
				Id:           uuid.Must(uuid.NewV4()).String(),
				Rank:         rank,
				FlagKey:      f.Key,
				NamespaceKey: doc.Namespace,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			if rollout.Threshold != nil {
				s.Threshold = &storage.RolloutThreshold{
					Percentage: rollout.Threshold.Percentage,
					Value:      rollout.Threshold.Value,
				}
				s.RolloutType = flipt.RolloutType_THRESHOLD_ROLLOUT_TYPE

				flagRollout.Type = s.RolloutType
				flagRollout.Rule = &flipt.Rollout_Threshold{
					Threshold: &flipt.RolloutThreshold{
						Percentage: rollout.Threshold.Percentage,
						Value:      rollout.Threshold.Value,
					},
				}
			} else if rollout.Segment != nil {
				var (
					segmentKeys = []string{}
					segments    = make(map[string]*storage.EvaluationSegment)
				)

				if rollout.Segment.Key != "" {
					segmentKeys = append(segmentKeys, rollout.Segment.Key)
				} else if len(rollout.Segment.Keys) > 0 {
					segmentKeys = append(segmentKeys, rollout.Segment.Keys...)
				}

				for _, segmentKey := range segmentKeys {
					segment, ok := ns.segments[segmentKey]
					if !ok {
						return errs.ErrInvalidf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, rank, segmentKey)
					}

					constraints := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
					for _, c := range segment.Constraints {
						constraints = append(constraints, storage.EvaluationConstraint{
							Operator: c.Operator,
							Property: c.Property,
							Type:     c.Type,
							Value:    c.Value,
						})
					}

					segments[segmentKey] = &storage.EvaluationSegment{
						SegmentKey:  segmentKey,
						MatchType:   segment.MatchType,
						Constraints: constraints,
					}
				}

				segmentOperator := flipt.SegmentOperator_value[rollout.Segment.Operator]

				s.Segment = &storage.RolloutSegment{
					Segments:        segments,
					SegmentOperator: flipt.SegmentOperator(segmentOperator),
					Value:           rollout.Segment.Value,
				}

				s.RolloutType = flipt.RolloutType_SEGMENT_ROLLOUT_TYPE

				frs := &flipt.RolloutSegment{
					Value:           rollout.Segment.Value,
					SegmentOperator: flipt.SegmentOperator(segmentOperator),
				}

				if len(segmentKeys) == 1 {
					frs.SegmentKey = segmentKeys[0]
				} else {
					frs.SegmentKeys = segmentKeys
				}

				flagRollout.Type = s.RolloutType
				flagRollout.Rule = &flipt.Rollout_Segment{
					Segment: frs,
				}
			}

			ns.rollouts[flagRollout.Id] = flagRollout

			evalRollouts = append(evalRollouts, s)
		}

		ns.evalRollouts[f.Key] = evalRollouts
	}

	ss.ns[doc.Namespace] = ns

	ss.evalDists = evalDists

	return nil
}

func (ss StoreSnapshot) String() string {
	return "snapshot"
}

func (ss *StoreSnapshot) GetRule(ctx context.Context, namespaceKey string, id string) (rule *flipt.Rule, _ error) {
	ns, err := ss.getNamespace(namespaceKey)
	if err != nil {
		return nil, err
	}

	var ok bool
	rule, ok = ns.rules[id]
	if !ok {
		return nil, errs.ErrNotFoundf(`rule "%s/%s"`, namespaceKey, id)
	}

	return rule, nil
