	}

	return *ns, nil
}
package fs

import (
	"context"
	"fmt"
	"path"

	"go.uber.org/zap"
)

// SnapshotSource produces instances of the storage snapshot.
// A single snapshot can be produced via Get or a channel
// may be provided to Subscribe in order to received
// new instances when new state becomes available.
type SnapshotSource interface {
	fmt.Stringer

	// Get builds a single instance of a *SnapshotSource
	Get() (*StoreSnapshot, error)

	// Subscribe feeds instances of *SnapshotSource onto the provided channel.
	// It should block until the provided context is cancelled (it will be called in a goroutine).
	// It should close the provided channel before it returns.
	Subscribe(context.Context, chan<- *StoreSnapshot)
}

// Store is an implementation of storage.Store backed by an SnapshotSource.
// The store subscribes to the source for instances of *SnapshotSource with new contents.
// When a new fs is received the contents is fetched and built into a snapshot
// of Flipt feature flag state.
type Store struct {
	*syncedStore

	logger *zap.Logger
	source SnapshotSource

	// notify is used for test purposes
	// it is invoked if defined when a snapshot update finishes
	notify func()

	cancel context.CancelFunc
	done   chan struct{}
}

func (l *Store) updateSnapshot(storeSnapshot *StoreSnapshot) {
	l.mu.Lock()
	l.Store = storeSnapshot
	l.mu.Unlock()

	// NOTE: this is really just a trick for unit tests
	// It is used to signal that an update occurred
	// so we dont have to e.g. sleep to know when
	// to check state.
	if l.notify != nil {
		l.notify()
	}
}

// NewStore constructs and configure a Store.
// The store creates a background goroutine which feeds a channel of *SnapshotSource.
func NewStore(logger *zap.Logger, source SnapshotSource) (*Store, error) {
	store := &Store{
		syncedStore: &syncedStore{},
		logger:      logger,
		source:      source,
		done:        make(chan struct{}),
	}

	// get an initial snapshot from source.
	f, err := source.Get()
	if err != nil {
		return nil, err
	}

	store.updateSnapshot(f)

	var ctx context.Context
	ctx, store.cancel = context.WithCancel(context.Background())

	ch := make(chan *StoreSnapshot)
	go source.Subscribe(ctx, ch)

	go func() {
		defer close(store.done)
		for snap := range ch {
			logger.Debug("received new snapshot")
			store.updateSnapshot(snap)
			logger.Debug("updated latest snapshot")
		}

		logger.Info("source subscription closed")
	}()

	return store, nil
}

// Close cancels the polling routine and waits for the routine to return.
func (l *Store) Close() error {
	l.cancel()

	<-l.done

	return nil
}

// String returns an identifier string for the store type.
func (l *Store) String() string {
	return path.Join("filesystem", l.source.String())
}

package local

import (
	"context"
	"os"
	"time"

	"go.flipt.io/flipt/internal/containers"
	storagefs "go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap"
)

// Source represents an implementation of an fs.FSSource for local
// updates on a FS.
type Source struct {
	logger *zap.Logger

	dir      string
	interval time.Duration
}

// NewSource constructs a Source.
func NewSource(logger *zap.Logger, dir string, opts ...containers.Option[Source]) (*Source, error) {
	s := &Source{
		logger:   logger,
		dir:      dir,
		interval: 10 * time.Second,
	}

	containers.ApplyAll(s, opts...)

	return s, nil
}

// WithPollInterval configures the interval in which we will restore
// the local fs.
func WithPollInterval(tick time.Duration) containers.Option[Source] {
	return func(s *Source) {
		s.interval = tick
	}
}

// Get returns an fs.FS for the local filesystem.
func (s *Source) Get() (*storagefs.StoreSnapshot, error) {
	return storagefs.SnapshotFromFS(s.logger, os.DirFS(s.dir))
}

// Subscribe feeds local fs.FS implementations onto the provided channel.
// It blocks until the provided context is cancelled.
func (s *Source) Subscribe(ctx context.Context, ch chan<- *storagefs.StoreSnapshot) {
	defer close(ch)

	ticker := time.NewTicker(s.interval)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			snap, err := s.Get()
			if err != nil {
				s.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			s.logger.Debug("updating local store snapshot")

			ch <- snap
		}
	}
}

// String returns an identifier string for the store type.
func (s *Source) String() string {
	return "local"
}
package git

import (
	"context"
	"errors"
	"fmt"
	"io/fs"
	"time"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/config"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/transport"
	"github.com/go-git/go-git/v5/storage/memory"
	"go.flipt.io/flipt/internal/containers"
	"go.flipt.io/flipt/internal/gitfs"
	storagefs "go.flipt.io/flipt/internal/storage/fs"
	"go.uber.org/zap"
)

// Source is an implementation of storage/fs.FSSource
// This implementation is backed by a Git repository and it tracks an upstream reference.
// When subscribing to this source, the upstream reference is tracked
// by polling the upstream on a configurable interval.
type Source struct {
	logger *zap.Logger
	repo   *git.Repository

	url      string
	ref      string
	hash     plumbing.Hash
	interval time.Duration
	auth     transport.AuthMethod
}

// WithRef configures the target reference to be used when fetching
// and building fs.FS implementations.
// If it is a valid hash, then the fixed SHA value is used.
// Otherwise, it is treated as a reference in the origin upstream.
func WithRef(ref string) containers.Option[Source] {
	return func(s *Source) {
		if plumbing.IsHash(ref) {
			s.hash = plumbing.NewHash(ref)
			return
		}

		s.ref = ref
	}
}

// WithPollInterval configures the interval in which origin is polled to
// discover any updates to the target reference.
func WithPollInterval(tick time.Duration) containers.Option[Source] {
	return func(s *Source) {
		s.interval = tick
	}
}

// WithAuth returns an option which configures the auth method used
// by the provided source.
func WithAuth(auth transport.AuthMethod) containers.Option[Source] {
	return func(s *Source) {
		s.auth = auth
	}
}

// NewSource constructs and configures a Source.
// The source uses the connection and credential details provided to build
// fs.FS implementations around a target git repository.
func NewSource(logger *zap.Logger, url string, opts ...containers.Option[Source]) (_ *Source, err error) {
	source := &Source{
		logger:   logger.With(zap.String("repository", url)),
		url:      url,
		ref:      "main",
		interval: 30 * time.Second,
	}
	containers.ApplyAll(source, opts...)

	field := zap.Stringer("ref", plumbing.NewBranchReferenceName(source.ref))
	if source.hash != plumbing.ZeroHash {
		field = zap.Stringer("SHA", source.hash)
	}
	source.logger = source.logger.With(field)

	source.repo, err = git.Clone(memory.NewStorage(), nil, &git.CloneOptions{
		Auth: source.auth,
		URL:  source.url,
	})
	if err != nil {
		return nil, err
	}

	return source, nil
}

// Get builds a new store snapshot based on the configure Git remote and reference.
func (s *Source) Get() (_ *storagefs.StoreSnapshot, err error) {
	var fs fs.FS
	if s.hash != plumbing.ZeroHash {
		fs, err = gitfs.NewFromRepoHash(s.logger, s.repo, s.hash)
	} else {
		fs, err = gitfs.NewFromRepo(s.logger, s.repo, gitfs.WithReference(plumbing.NewRemoteReferenceName("origin", s.ref)))
	}
	if err != nil {
		return nil, err
	}

	return storagefs.SnapshotFromFS(s.logger, fs)
}

// Subscribe feeds gitfs implementations of fs.FS onto the provided channel.
// It blocks until the provided context is cancelled (it will be called in a goroutine).
// It closes the provided channel before it returns.
func (s *Source) Subscribe(ctx context.Context, ch chan<- *storagefs.StoreSnapshot) {
	defer close(ch)

	// NOTE: theres is no point subscribing to updates for a git Hash
	// as it is atomic and will never change.
	if s.hash != plumbing.ZeroHash {
		s.logger.Info("skipping subscribe as static SHA has been configured")
		return
	}

	ticker := time.NewTicker(s.interval)
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			s.logger.Debug("fetching from remote")
			if err := s.repo.Fetch(&git.FetchOptions{
				Auth: s.auth,
				RefSpecs: []config.RefSpec{
					config.RefSpec(fmt.Sprintf(
						"+%s:%s",
						plumbing.NewBranchReferenceName(s.ref),
						plumbing.NewRemoteReferenceName("origin", s.ref),
					)),
				},
			}); err != nil {
				if errors.Is(err, git.NoErrAlreadyUpToDate) {
					s.logger.Debug("store already up to date")
					continue
				}

				s.logger.Error("failed fetching remote", zap.Error(err))
				continue
			}

			snap, err := s.Get()
			if err != nil {
				s.logger.Error("failed creating snapshot from fs", zap.Error(err))
				continue
			}

			ch <- snap

			s.logger.Debug("finished fetching from remote")
		}
	}
}

// String returns an identifier string for the store type.
func (*Source) String() string {
	return "git"
}

